create or replace function spiritual.compute_planetary_hours ( p_date date, p_sunrise timestamptz, p_sunset timestamptz, p_next_sunrise timestamptz ) returns table ( hour_index smallint, planet text, start_utc timestamptz, end_utc timestamptz, is_daytime boolean ) language plpgsql stable as $$ declare day_ms numeric; night_ms numeric; day_hour_ms numeric; night_hour_ms numeric; day_ruler text; start_idx smallint; planet_idx smallint; begin day_ms := extract(epoch from p_sunset - p_sunrise) * 1000; night_ms := extract(epoch from p_next_sunrise - p_sunset) * 1000; day_hour_ms := day_ms / 12.0; night_hour_ms := night_ms / 12.0; select dr.planet into day_ruler from spiritual.day_rulers dr where dr.day_of_week = extract(dow from p_date)::smallint; select co.idx into start_idx from spiritual.chaldean_order co where co.planet = day_ruler; for i in 0..23 loop planet_idx := (start_idx + i) % 7; select co.planet into planet from spiritual.chaldean_order co where co.idx = planet_idx; hour_index := i; is_daytime := i < 12; if is_daytime then start_utc := p_sunrise + ((i * day_hour_ms) / 1000.0) * interval '1 second'; end_utc := p_sunrise + (((i + 1) * day_hour_ms) / 1000.0) * interval '1 second'; else start_utc := p_sunset + (((i - 12) * night_hour_ms) / 1000.0) * interval '1 second'; if i < 23 then end_utc := p_sunset + (((i - 12 + 1) * night_hour_ms) / 1000.0) * interval '1 second'; else end_utc := p_next_sunrise; end if; end if; return next; end loop; end; $$;
